-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(materialized='table') }}

with
dim_product_source as (
    select
        product_code,
        product_name,
        product_brand,
        product_category,
        product_list_price,
        line_order_date
    from {{ ref("ecommerce__order_star__base") }}
),
dim_product_ranked as (
    select
        product_code,
        product_name,
        product_brand,
        product_category,
        product_list_price,
        row_number() over (partition by product_code order by line_order_date desc) as dpf_version_rank
    from dim_product_source
),
dim_product_current as (
    select
        product_code,
        product_name,
        product_brand,
        product_category,
        product_list_price
    from dim_product_ranked
    where dpf_version_rank = 1
)

select
    cast(product_code as {{ dpf_type('string') }}) as product_code,
    cast(product_name as {{ dpf_type('string') }}) as product_name,
    cast(product_brand as {{ dpf_type('string') }}) as product_brand,
    cast(product_category as {{ dpf_type('string') }}) as product_category,
    cast(product_list_price as {{ dpf_decimal_type(12, 2) }}) as product_list_price
from dim_product_current
